-- ============================================================
-- EX 603 reference dataset: Airline / Travel Booking
-- Generated deterministically (seed 603). Do not edit by hand.
-- Load with:  createdb ex603_airline && psql -d ex603_airline -f airline.sql
-- ============================================================
-- PostgreSQL load:  createdb ex603_airline  &&  psql -d ex603_airline -f airline.sql
-- (Re-running is safe: every table is dropped first, children before parents.)
DROP TABLE IF EXISTS bookings CASCADE;
DROP TABLE IF EXISTS flight_routes CASCADE;
DROP TABLE IF EXISTS flight_services CASCADE;
DROP TABLE IF EXISTS airports CASCADE;
DROP TABLE IF EXISTS flights CASCADE;
DROP TABLE IF EXISTS passengers CASCADE;

-- ---------- actor ----------
CREATE TABLE passengers (
    passenger_id        INT           NOT NULL,
    passenger_name      VARCHAR(120)  NOT NULL,
    signup_date      DATE          NOT NULL,
    home_country    VARCHAR(80)   NOT NULL,
    email    VARCHAR(160)  NOT NULL,
    referred_by INT           NULL,
    is_active      BOOLEAN       NOT NULL DEFAULT TRUE,
    PRIMARY KEY (passenger_id),
    CONSTRAINT uq_passengers_email UNIQUE (email),
    CONSTRAINT ck_passengers_no_self CHECK (referred_by IS NULL OR referred_by <> passenger_id),
    CONSTRAINT fk_passengers_ref FOREIGN KEY (referred_by)
        REFERENCES passengers (passenger_id) ON DELETE SET NULL
);

-- ---------- producer ----------
CREATE TABLE flights (
    flight_id        INT           NOT NULL,
    flight_number      VARCHAR(120)  NOT NULL,
    first_scheduled_on      DATE          NOT NULL,
    origin_country    VARCHAR(80)   NOT NULL,
    tail_number    VARCHAR(60)   NOT NULL,
    seat_capacity    SMALLINT NOT NULL,
    is_active      BOOLEAN       NOT NULL DEFAULT TRUE,
    PRIMARY KEY (flight_id),
    CONSTRAINT uq_flights_tail_number UNIQUE (tail_number),
    CONSTRAINT ck_flights_metric CHECK (seat_capacity > 0)
);

-- ---------- multivalued attribute, resolved ----------
CREATE TABLE flight_services (
    flight_id   INT       NOT NULL,
    service_code  CHAR(2) NOT NULL,
    PRIMARY KEY (flight_id, service_code),
    CONSTRAINT fk_flight_services_owner FOREIGN KEY (flight_id)
        REFERENCES flights (flight_id) ON DELETE CASCADE
);

-- ---------- catalog ----------
CREATE TABLE airports (
    airport_id    INT          NOT NULL,
    iata_code  VARCHAR(60)  NOT NULL,
    airport_name  VARCHAR(200) NULL,
    PRIMARY KEY (airport_id),
    CONSTRAINT uq_airports_name UNIQUE (iata_code)
);

-- ---------- junction: producer to catalog, composite PK ----------
CREATE TABLE flight_routes (
    flight_id   INT  NOT NULL,
    airport_id   INT  NOT NULL,
    effective_from DATE NOT NULL,
    PRIMARY KEY (flight_id, airport_id),
    CONSTRAINT fk_flight_routes_prod FOREIGN KEY (flight_id)
        REFERENCES flights (flight_id) ON DELETE CASCADE,
    CONSTRAINT fk_flight_routes_cat FOREIGN KEY (airport_id)
        REFERENCES airports (airport_id) ON DELETE RESTRICT
);

-- ---------- event: the high volume fact table ----------
CREATE TABLE bookings (
    booking_id       BIGINT        NOT NULL,
    passenger_id       INT           NOT NULL,
    flight_id       INT           NOT NULL,
    booked_at       TIMESTAMP      NOT NULL,
    checked_in_at      TIMESTAMP      NULL,
    booking_country   VARCHAR(80)   NOT NULL,
    fare_paid   DECIMAL(9,2) NOT NULL,
    bags_kg   DECIMAL(7,2) NOT NULL,
    fare_multiplier    DECIMAL(4,2)  NOT NULL DEFAULT 1.00,
    booking_status   VARCHAR(20)   NOT NULL,
    cancellation_reason   VARCHAR(60)   NULL,     -- nullable by design
    PRIMARY KEY (booking_id),
    CONSTRAINT ck_bookings_metric_pos  CHECK (fare_paid >= 0),
    CONSTRAINT ck_bookings_second_pos  CHECK (bags_kg > 0),
    CONSTRAINT ck_bookings_third_min   CHECK (fare_multiplier >= 1.00),
    CONSTRAINT ck_bookings_time_order  CHECK (checked_in_at IS NULL OR checked_in_at >= booked_at),
    CONSTRAINT fk_bookings_actor FOREIGN KEY (passenger_id)
        REFERENCES passengers (passenger_id) ON DELETE RESTRICT,
    CONSTRAINT fk_bookings_prod FOREIGN KEY (flight_id)
        REFERENCES flights (flight_id) ON DELETE RESTRICT
);

